function runQuery(rawText) {
  const q = rawText.trim().toLowerCase();
  const normalized = q.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");

  const numMatch = q.match(/(\d+)\s*\.?\s*(gündem|haber|madde|sıra|detay)?/);
  if (numMatch && (q.includes("gündem") || q.includes("haber") || q.includes("detay") || q.includes("madde") || q.trim().length <= 10)) {
    const idx = parseInt(numMatch[1], 10) - 1; const found = state.lastShownAgenda[idx];
    return found ? `<strong>#${idx + 1} ${found.cat} — ${found.title}</strong><br/>${found.summary}<br/><span class="meta">Durum: ${found.currentState}</span>` : `Listedeki ${idx + 1}. kayıt bulunamadı.`;
  }

  const wantsHistory = /(tarih|tarihçe|antik|orta cag|modern|period|donem|medeni|uygarl|icat|koken|tarih oncesi|2026|mogol|roma|han çin|pandemi|savas)/i.test(normalized);
  if (wantsHistory) {
    const stopWords = new Set(["tarih", "tarihi", "tarihce", "ozet", "ozetle", "liste", "tablo", "sor", "soru", "yaz", "hikaye", "senaryo", "sinav", "test", "hakkinda", "bilgi", "goster", "ver", "bir", "birlikte", "icin", "ve", "ya", "detay"]);
    const terms = normalized.split(/[^a-z0-9çğıöşü]+/i).filter(t => t && !stopWords.has(t));
    let matches = state.historyItems.filter(h => {
      const haystack = [h.cat, h.period, h.title, h.summary, h.places, ...h.concepts].join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
      return terms.some(term => haystack.includes(term)) || terms.length === 0;
    });

    if (!matches.length) matches = state.historyItems;

    if (/^(ozet|kisa ozet|tarih ozeti|tarihi ozet)/.test(normalized)) {
      const list = matches.slice(0, 8);
      return `<strong>🏛️ Kronolojik özet:</strong><br/>` + list.map(h => `• <strong>${h.period} — ${h.title}</strong>: ${h.summary}`).join("<br/>");
    }
    if (/tablo|liste/.test(normalized)) {
      const rows = matches.map(h => `<tr><td>${h.period}</td><td>${h.title}</td><td>${h.places}</td></tr>`).join("");
      return `<strong>📊 Tarih tablosu</strong><br/><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left;border-bottom:1px solid #25324d;padding:6px">Dönem</th><th style="text-align:left;border-bottom:1px solid #25324d;padding:6px">Olay</th><th style="text-align:left;border-bottom:1px solid #25324d;padding:6px">Mekânlar</th></tr></thead><tbody>${rows}</tbody></table>`;
    }
    if (/zaman çizelgesi|zaman cizelgesi|timeline|kronoloji/.test(normalized)) {
      return `<strong>🗺️ Zaman çizelgesi:</strong><br/>` + matches.slice().sort((a, b) => state.historyItems.indexOf(a) - state.historyItems.indexOf(b)).map(h => `• <strong>${h.period}</strong> — ${h.title}`).join("<br/>");
    }
    if (/quiz|soru|test|sinav/.test(normalized)) {
      const q1 = matches[0]; const q2 = matches[1] || state.historyItems[0];
      return `<strong>🧠 Tarih öz testi</strong><br/>1. ${q1.title} hangi mekânlarla ilişkilendirilmiştir?<br/><span class="meta">Yanıt: ${q1.places}</span><br/><br/>2. ${q2.period} döneminde hangi dönüşüm öne çıkar?<br/><span class="meta">Yanıt: ${q2.title}</span>`;
    }
    if (/hikaye|story|senaryo/.test(normalized)) {
      const h = matches[0];
      return `<strong>📖 Bağlam temelli kısa senaryo</strong><br/>${h.period} döneminde ${h.places} çevresinde yaşayanlar, “${h.title}” bağlamındaki ${h.concepts.slice(0, 3).join(", ")} gerçeklerini deneyimler. Bu senaryo arşivdeki özet bilgilerden oluşturulmuştur; bireysel karakterler veya ayrıntılı konuşmalar uydurulmamıştır. Bağlam: ${h.summary}`;
    }
    if (/karsilastir|analiz|neden|sonuc|etki/.test(normalized)) {
      const h = matches[0];
      return `<strong>🏛️ Tarihsel bağlam analizi:</strong><br/><strong>${h.title}</strong><br/>${h.summary}<br/><span class="meta">Bağlam: ${h.places}. Kavramlar: ${h.concepts.join(", ")}. Bu sonuç arşivdeki bilgilere dayanır; kesin olmayan veya arşivde bulunmayan veriler belirtilmez.</span>`;
    }

    const list = matches.slice(0, 12);
    return "<strong>🏛️ Tarih Arşivi · Eşleşen kayıtlar:</strong><br/>" + list.map(m => `• <strong>[${m.period} · ${m.cat}] ${m.title}:</strong> ${m.summary} <span class="meta">Mekânlar: ${m.places} · Kavramlar: ${m.concepts.join(", ")}</span>`).join("<br/> ") + (matches.length > list.length ? `<br/><span class="meta">Toplam eşleşme: ${matches.length}. Daha dar bir dönem, mekân veya kavram sorabilirsiniz.</span>` : "");
  }

  if (/(teknoloji|yapay zeka|ai|çip|robot|uzay|gelişen)/i.test(q)) return "<strong>⚡ Gelişen Teknoloji:</strong><br/>" + state.techItems.map(t => `• <strong>[${t.tag}] ${t.title}:</strong> ${t.detail}`).join("<br/> ");
  return "Gündem, teknoloji veya tarihçe için anahtar kelime ya da sayısal gündem sırası (örn: '2. gündem detayı') girebilirsiniz. Tarihte özet, tablo, zaman çizelgesi, quiz, hikâye veya analiz isteyebilirsiniz.";
}

