125:   for (const block of itemMatches) {
126:     const get = (tag) => block.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'))?.[1] || '';
127:     const title = cleanText(get('title'));
