132:     const pipeMatch = title.match(/\s*\|\s*([^|]+)$/);
133:     const suffixMatch = dashMatch || pipeMatch;
134:     const source = cleanText(sourceTag || (suffixMatch ? suffixMatch[1] : ''));
135:     const headline = cleanText(suffixMatch ? title.slice(0, suffixMatch.index).trim() : title);
136:     const description = cleanText(get('description'));
137:     const titleKey = headline.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
138:     const descriptionKey = description.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
139:     const snippet = !description || descriptionKey === titleKey || descriptionKey.includes(titleKey) || titleKey.includes(descriptionKey) ? '' : description;
140:     items.push({
