    .replace(/&nbsp;/gi, ' ')
    .replace(/&(amp|#0*38);/gi, '&')
    .replace(/&(quot|#0*34);/gi, '"')
    .replace(/&(apos|#0*39);/gi, "'")
    .replace(/&(lt|#0*60);/gi, '<')
    .replace(/&(gt|#0*62);/gi, '>')
    .replace(/&#(\d+);/g, (_, code) => { const n = Number(code); return Number.isInteger(n) && n <= 0x10ffff ? String.fromCodePoint(n) : ''; })
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => { const n = Number.parseInt(code, 16); return Number.isInteger(n) && n <= 0x10ffff ? String.fromCodePoint(n) : ''; })
    .replace(/<[^>]*>/g, ' ');
  return text.replace(/\s+/g, ' ').trim();
}

function normalizeItem(item) {
  if (!item) return null;
  const title = cleanText(item.title).slice(0, 300);
  const url = validHttpUrl(item.url);
  if (!title || !url) return null;
  let snippet = cleanText(item.snippet);
  const titleKey = title.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  const snippetKey = snippet.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  if (!snippet || snippetKey === titleKey || (snippetKey && titleKey && (snippetKey.includes(titleKey) || titleKey.includes(snippetKey)))) snippet = '';
  const source = cleanText(item.source);
  return { title, url, snippet: snippet.slice(0, 1200), source: source.slice(0, 200), date: cleanText(item.date).slice(0, 100) };
}

function dedupeAndSort(items) {
  const seen = new Set();
  return items.map(normalizeItem).filter(Boolean).filter((item) => {
    let key;
    try {
      const url = new URL(item.url);
      url.hash = '';
      url.searchParams.delete('utm_source'); url.searchParams.delete('utm_medium'); url.searchParams.delete('utm_campaign');
      key = `${url.origin}${url.pathname.replace(/\/$/, '')}`.toLocaleLowerCase('tr-TR');
    } catch { key = item.url.toLocaleLowerCase('tr-TR'); }
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).sort((a, b) => {
    const timestamp = (item) => {
      const value = Date.parse(item.date);
      return Number.isFinite(value) ? value : 0;
    };
    return timestamp(b) - timestamp(a);
  });
}

function buildMeaningfulQuery(raw) {
  let query = String(raw || '').replace(/\s+/g, ' ').trim();
  const normalized = query.toLocaleLowerCase('tr-TR').replace(/[?!.]+$/g, '').trim();
  if (/^(gündemde ne var|gundemde ne var|gündem|gundem|günse|gunse|bugün neler oldu|bugun neler oldu|son gelişmeler|son gelismeler|haberler|güncel haberler|guncel haberler)$/.test(normalized)) {
    return 'Türkiye ve dünya gündem son dakika haberleri';
  }
  return query
    .replace(/^(lütfen\s+|lutfen\s+|please\s+|can you\s+|could you\s+)/i, '')
    .replace(/\b(arastir|araştır|araştırma|google'da bul|google da bul|kontrol et|kaynak getir|search the web|look up|get sources?)\b/gi, '')
    .replace(/[?!.]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim().slice(0, MAX_QUERY_LENGTH);
}

function validHttpUrl(value) {
  try {
    const url = new URL(value);
    return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : '';
  } catch {
    return '';
  }
}

async function googleSearch(apiKey, cx, query, count) {
  const params = new URLSearchParams({ key: apiKey, cx, q: query, num: String(count), hl: 'tr', gl: 'tr' });
  const response = await fetch('https://www.googleapis.com/customsearch/v1?' + params.toString(), {
    method: 'GET',
    headers: { Accept: 'application/json', 'User-Agent': 'FoVerse-AI-Search/1.0' },
  });
  if (!response.ok) throw new Error(`Google search failed: ${response.status}`);
  const data = await response.json();
  return (Array.isArray(data.items) ? data.items : []).slice(0, count).map((item) => ({
    title: cleanText(item.title || 'Kaynak').slice(0, 300),
    url: validHttpUrl(item.link),
    snippet: cleanText(item.snippet || '').slice(0, 1200),
    source: cleanText(item.displayLink || new URL(item.link).hostname).slice(0, 200),
    date: String(item.pagemap?.metatags?.[0]?.['article:published_time'] || item.pagemap?.metatags?.[0]?.date || '').slice(0, 100),
  })).filter((item) => item.url);
}

async function rssSearch(query, count) {
  const params = new URLSearchParams({ q: query, hl: 'tr', gl: 'TR', ceid: 'TR:tr' });
  const response = await fetch('https://news.google.com/rss/search?' + params.toString(), {
    method: 'GET',
    headers: { Accept: 'application/rss+xml, application/xml;q=0.9, text/xml;q=0.8', 'User-Agent': 'FoVerse-AI-Search/1.0' },
  });
  if (!response.ok) throw new Error(`Google News RSS failed: ${response.status}`);
  const xml = await response.text();
  const items = [];
  const itemMatches = xml.match(/<item\b[^>]*>[\s\S]*?<\/item>/gi) || [];
  for (const block of itemMatches) {
    const get = (tag) => block.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'))?.[1] || '';
    const title = cleanText(get('title'));
    const url = validHttpUrl(cleanText(get('link')));
    if (!title || !url) continue;
    const sourceTag = cleanText(get('source'));
    const dashMatch = title.match(/\s+-\s+([^]+)$/);
    const pipeMatch = title.match(/\s*\|\s*([^|]+)$/);
    const suffixMatch = dashMatch || pipeMatch;
    const source = cleanText(sourceTag || (suffixMatch ? suffixMatch[1] : ''));
    const headline = cleanText(suffixMatch ? title.slice(0, suffixMatch.index).trim() : title);
    const description = cleanText(get('description'));
    const titleKey = headline.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
    const descriptionKey = description.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
    const snippet = !description || descriptionKey === titleKey || descriptionKey.includes(titleKey) || titleKey.includes(descriptionKey) ? '' : description;
    items.push({
      title: headline.slice(0, 300),
      url,
      snippet: snippet.slice(0, 1200),
      source,
      date: cleanText(get('pubDate')).slice(0, 100),
    });
    if (items.length >= count) break;
  }
  return items;
}

async function fetchWithTimeout(operation, timeoutMs = SOURCE_TIMEOUT_MS) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await operation(controller.signal);
  } finally {
    clearTimeout(timeout);
  }
}

function buildDetailFallbackQuery(query) {
  const stopWords = new Set(['haber', 'haberi', 'detay', 'detayi', 'detaylari', 'hakkinda', 'biraz', 'daha', 'fazla', 'ver', 'verir', 'misin', 'mi', 'icin', 'ile', 've', 'bu', 'son', 'dakika', 'abd', 'baskan', 'baskani', 'olacak', 'oldu', 'oluyor', 'katilacak']);
  const tokens = buildMeaningfulQuery(query).split(/\s+/).map((token) => token.replace(/[’'].*$/, '').replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, ''));
  const useful = tokens.filter((token) => {
    const normalized = token.toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ı/g, 'i');
    return token && !stopWords.has(normalized) && !/^(?:edecek|ediyor|etti|acikladi|duyurdu)$/.test(normalized);
  });
  const priority = (token) => {
    const normalized = token.toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ı/g, 'i');
    if (normalized === 'nato') return 100;
    if (/^zirve/.test(normalized)) return 90;
    if (normalized === 'trump') return 80;
    if (normalized === 'turkiye') return 70;
    return Math.min(token.length, 20);
  };
  const limit = useful.length > 4 ? 4 : Math.max(1, useful.length - 1);
  return useful.map((token, index) => ({ token, index }))
    .sort((a, b) => priority(b.token) - priority(a.token) || a.index - b.index)
    .slice(0, limit)
    .map(({ token }) => token)
    .join(' ');
}

async function searchSources(query, count, apiKey, cx) {
  if (apiKey && cx) {
    try {
      const items = await fetchWithTimeout((signal) => {
        const params = new URLSearchParams({ key: apiKey, cx, q: query, num: String(count), hl: 'tr', gl: 'tr' });
        return fetch('https://www.googleapis.com/customsearch/v1?' + params.toString(), {
          method: 'GET', headers: { Accept: 'application/json', 'User-Agent': 'FoVerse-AI-Search/1.0' }, signal,
        }).then(async (response) => {
          if (!response.ok) throw new Error(`Google search failed: ${response.status}`);
          const data = await response.json();
          return (Array.isArray(data.items) ? data.items : []).slice(0, count).map((item) => {
            const url = validHttpUrl(item.link);
            let source = cleanText(item.displayLink);
            try { if (!source) source = cleanText(new URL(url).hostname); } catch {}
            return {
              title: cleanText(item.title || 'Kaynak').slice(0, 300), url,
              snippet: cleanText(item.snippet || '').slice(0, 1200), source,
              date: cleanText(item.pagemap?.metatags?.[0]?.['article:published_time'] || item.pagemap?.metatags?.[0]?.date || '').slice(0, 100),
            };
          }).filter((item) => item.url);
        });
      });
      const normalized = dedupeAndSort(items).slice(0, count);
      if (normalized.length) return { items: normalized, source: 'google' };
    } catch (_) {
      // Continue to keyless sources.
    }
  }

  try {
    const items = await fetchWithTimeout((signal) => {
      const params = new URLSearchParams({ q: query, hl: 'tr', gl: 'TR', ceid: 'TR:tr' });
      return fetch('https://news.google.com/rss/search?' + params.toString(), {
        method: 'GET', headers: { Accept: 'application/rss+xml, application/xml;q=0.9, text/xml;q=0.8', 'User-Agent': 'FoVerse-AI-Search/1.0' }, signal,
      }).then(async (response) => {
        if (!response.ok) throw new Error(`Google News RSS failed: ${response.status}`);
        return rssSearchResult(await response.text(), count);
      });
    });
    const normalized = dedupeAndSort(items).slice(0, count);
    if (normalized.length) return { items: normalized, source: 'google_news_rss' };
  } catch (_) {
    // Continue to the independent, keyless GDELT article API.
  }

  try {
    const items = await fetchWithTimeout((signal) => gdeltSearch(query, count, signal));
    const normalized = dedupeAndSort(items).slice(0, count);
    if (normalized.length) return { items: normalized, source: 'gdelt' };
  } catch (_) {
    // The caller can try a shorter detail query before reporting failure.
  }
  return null;
}

module.exports = async function handler(req, res) {
  const ping = req.query && req.query.ping === '1';
  const pingFromUrl = typeof req.url === 'string' && /(?:[?&])ping=1(?:&|$)/.test(req.url);
  if (ping || pingFromUrl) {
    return reply(res, 200, { ok: true, commit: 'ping-test', node: process.version });
  }

  try {

  if (req.method !== 'POST' && req.method !== 'GET') {
    res.set('Allow', 'GET, POST');
    return reply(res, 405, { error: 'Only GET and POST are supported.' });
  }

  let body = req.body;
  if (req.method === 'GET') {
    const queryParams = req.query || {};
    let query = queryParams.q ?? queryParams.query;
    if (query === undefined && typeof req.url === 'string') {
      try {
        const url = new URL(req.url, 'http://localhost');
        query = url.searchParams.get('q') ?? url.searchParams.get('query');
      } catch {}
    }
    body = { query, count: queryParams.count };
  }
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { return reply(res, 400, { error: 'Geçersiz istek gövdesi.' }); }
  }
  const rawQuery = typeof body?.query === 'string' ? body.query.trim() : '';
  if (!rawQuery || rawQuery.length > MAX_QUERY_LENGTH) {
    return reply(res, 400, { error: 'Sorgu boş olamaz ve 500 karakteri aşamaz.' });
  }
  const count = Math.max(1, Math.min(MAX_RESULTS, Number.parseInt(body?.count, 10) || MAX_RESULTS));
  const query = buildMeaningfulQuery(rawQuery);

  const apiKey = process.env.GOOGLE_SEARCH_API_KEY;
  const cx = process.env.GOOGLE_SEARCH_CX;
  const detailPattern = /(?:detay|detaylandır|detaylandir|ayrıntı|ayrinti|hakkında|hakkinda|biraz daha)/i;
  const isDetailSearch = detailPattern.test(rawQuery) || /^\s*[1-9]\d?\s*[.)]?\s*(?:Haber|Madde|Başlık)/i.test(rawQuery);

  let result = await searchSources(query, count, apiKey, cx);
  if (!result && isDetailSearch) {
    const fallbackQuery = buildDetailFallbackQuery(rawQuery);
    if (fallbackQuery && fallbackQuery !== query) {
      result = await searchSources(fallbackQuery, count, apiKey, cx);
      if (result) return reply(res, 200, { items: result.items, source: result.source, query: fallbackQuery });
    }
  }
  if (result) return reply(res, 200, { items: result.items, source: result.source, query });

  return reply(res, 502, {
    error: 'Canlı web araması şu anda kullanılamıyor; haber kaynağına ve yedek arama katmanına ulaşılamadı.',
    code: 'LIVE_SEARCH_UNAVAILABLE',
  });
  } catch (err) {
    return reply(res, 502, {
      error: 'Arama işlenirken beklenmeyen bir hata oluştu; sorgu güvenli biçimde durduruldu.',
      code: 'LIVE_SEARCH_RUNTIME_ERROR',
    });
  }
}

function rssSearchResult(xml, count) {
  const items = [];
  const itemMatches = xml.match(/<item\b[^>]*>[\s\S]*?<\/item>/gi) || [];
  for (const block of itemMatches) {
    const get = (tag) => block.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'))?.[1] || '';
    const title = cleanText(get('title'));
    const url = validHttpUrl(cleanText(get('link')));
    if (!title || !url) continue;
    const sourceTag = cleanText(get('source'));
    const dashMatch = title.match(/\s+-\s+([^]+)$/);
    const pipeMatch = title.match(/\s*\|\s*([^|]+)$/);
    const suffixMatch = dashMatch || pipeMatch;
    const source = cleanText(sourceTag || (suffixMatch ? suffixMatch[1] : ''));
    const headline = cleanText(suffixMatch ? title.slice(0, suffixMatch.index).trim() : title);
    const description = cleanText(get('description'));
    const titleKey = headline.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
    const descriptionKey = description.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
    const snippet = !description || descriptionKey === titleKey || descriptionKey.includes(titleKey) || titleKey.includes(descriptionKey) ? '' : description;
    items.push({
      title: headline.slice(0, 300), url,
      snippet: snippet.slice(0, 1200),
      source,
      date: cleanText(get('pubDate')).slice(0, 100),
    });
    if (items.length >= count) break;
  }
  return dedupeAndSort(items).slice(0, count);
}

async function gdeltSearch(query, count, signal) {
  const params = new URLSearchParams({
    query,
    mode: 'ArtList',
    format: 'json',
    maxrecords: String(count),
    sort: 'HybridRel',
  });
  const response = await fetch(`https://api.gdeltproject.org/api/v2/doc/doc?${params}`, {
    method: 'GET',
    headers: { Accept: 'application/json', 'User-Agent': 'FoVerse-AI-Search/1.0' },
    signal,
  });
  if (!response.ok) throw new Error(`GDELT search failed: ${response.status}`);
  const data = await response.json();
  return (Array.isArray(data.articles) ? data.articles : []).slice(0, count).map((article) => {
    const url = validHttpUrl(article.url);
    let source = cleanText(article.domain);
    try { if (!source && url) source = cleanText(new URL(url).hostname); } catch {}
    return {
      title: cleanText(article.title || 'Kaynak').slice(0, 300),
      url,
      snippet: cleanText(article.snippet || '').slice(0, 1200),
      source: source.slice(0, 200),
      date: cleanText(article.seendate || article.datetime || '').slice(0, 100),
    };
  }).filter((item) => item.title && item.url);
}
'use strict';

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const searchHandler = require('./api/search');

const PORT = Number(process.env.PORT) || 3000;
const MAX_BODY_BYTES = 16 * 1024;

function sendJson(res, status, payload) {
  res.writeHead(status, {
    'Cache-Control': 'no-store',
    'Content-Type': 'application/json; charset=utf-8',
  });
  res.end(JSON.stringify(payload));
}

async function readBody(req, res) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) {
      sendJson(res, 413, { error: 'İstek gövdesi çok büyük.' });
      return null;
    }
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}

function createServer() {
  return http.createServer(async (req, res) => {
    const pathname = new URL(req.url, 'http://localhost').pathname;

    if (pathname === '/api/search' || pathname === '/api/search/') {
      const body = await readBody(req, res);
      if (body === null) return;

      const handlerResponse = {
        statusCode: 200,
        headers: {},
        status(code) { this.statusCode = code; return this; },
        set(name, value) { this.headers[name] = value; return this; },
        json(payload) {
          res.writeHead(this.statusCode, {
            ...this.headers,
            'Content-Type': 'application/json; charset=utf-8',
          });
          res.end(JSON.stringify(payload));
          return this;
        },
      };

      await searchHandler({ method: req.method, body, url: req.url, query: Object.fromEntries(new URL(req.url, 'http://localhost').searchParams) }, handlerResponse);
      return;
    }

    if (pathname === '/' && req.method === 'GET') {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      fs.createReadStream(path.join(__dirname, 'index.html')).pipe(res);
      return;
    }

    if (pathname === '/assets/cosmic-black-hole-space-live-wallpaper.mp4' && (req.method === 'GET' || req.method === 'HEAD')) {
      const filePath = path.join(__dirname, 'assets', 'cosmic-black-hole-space-live-wallpaper.mp4');
      fs.stat(filePath, (err, stat) => {
        if (err) return sendJson(res, 404, { error: 'Video not found.' });
        const headers = { 'Content-Type': 'video/mp4', 'Accept-Ranges': 'bytes', 'Cache-Control': 'public, max-age=86400' };
        const range = req.headers.range;
        if (!range) {
          res.writeHead(200, { ...headers, 'Content-Length': stat.size });
          if (req.method === 'HEAD') return res.end();
          fs.createReadStream(filePath).pipe(res);
          return;
        }
        const match = /^bytes=(\d*)-(\d*)$/.exec(range);
        if (!match) {
          res.writeHead(416, { ...headers, 'Content-Range': `bytes */${stat.size}` });
          return res.end();
        }
        const start = match[1] ? Number(match[1]) : 0;
        const end = match[2] ? Math.min(Number(match[2]), stat.size - 1) : stat.size - 1;
        if (!Number.isFinite(start) || start >= stat.size || end < start) {
          res.writeHead(416, { ...headers, 'Content-Range': `bytes */${stat.size}` });
          return res.end();
        }
        res.writeHead(206, { ...headers, 'Content-Length': end - start + 1, 'Content-Range': `bytes ${start}-${end}/${stat.size}` });
        if (req.method === 'HEAD') return res.end();
        fs.createReadStream(filePath, { start, end }).pipe(res);
      });
      return;
    }

    sendJson(res, 404, { error: 'Not found.' });
  });
}

if (require.main === module) {
  createServer().listen(PORT, '0.0.0.0', () => {
    console.log(`PlayGround server listening on port ${PORT}`);
  });
}

module.exports = { createServer };
