445:     function historySearchMatches(rawText) {
446:       const normalized = rawText.toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
447:       const stopWords = new Set(["tarih", "tarihi", "tarihce", "ozet", "ozetle", "liste", "tablo", "soru", "sor", "yaz", "hikaye", "senaryo", "sinav", "test", "hakkinda", "bilgi", "goster", "ver", "bir", "icin", "ve", "detay", "ara", "goster"]);
448:       const terms = normalized.split(/[^a-z0-9]+/i).filter(t => t && !stopWords.has(t));
449:       if (!terms.length) return [];
450:       return state.historyItems.map(h => {
451:         const searchable = [h.cat, h.period, h.title, h.summary, h.places, ...(h.people || []), ...(h.keywords || h.concepts || [])].join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
452:         let score = 0;
453:         terms.forEach(term => {
454:           if ((h.title || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 5;
455:           if ((h.period || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 4;
456:           if ((h.places || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 3;
457:           if ((h.people || []).join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 3;
458:           if (searchable.includes(term)) score += 1;
459:         });
460:         return { item: h, score };
461:       }).filter(match => match.score > 0).sort((a, b) => b.score - a.score).map(match => match.item);
462:     }
