document.querySelectorAll('.mode-row button').forEach(b=>b.addEventListener('click',()=>{try{document.querySelectorAll('.mode-row button').forEach(x=>x.classList.remove('active'));b.classList.add('active');mode=b.dataset.mode;$('modeBadge').textContent=mode;store.set('geminiMode',mode)}catch(e){}}));
document.querySelectorAll('.suggestion').forEach(b=>b.addEventListener('click',()=>{try{$('input').value=b.dataset.prompt||'';autoGrow();$('input').focus()}catch(e){}}));
$('addBtn').addEventListener('click',()=>{try{$('fileInput').click()}catch(e){}});$('fileInput').addEventListener('change',async e=>{try{const f=e.target.files&&e.target.files[0];if(!f)return;if(f.size>2*1024*1024){$('attachedName').textContent='File too large (2 MB limit)';$('attached').classList.add('show');return}attachedName=f.name;attachedText=await f.text();$('attachedName').textContent=f.name+' · '+Math.ceil(f.size/1024)+' KB';$('attached').classList.add('show')}catch(e){attachedText='';$('attachedName').textContent='Could not read file';$('attached').classList.add('show')}});$('removeFile').addEventListener('click',()=>{try{attachedText='';attachedName='';$('attached').classList.remove('show');$('fileInput').value=''}catch(e){}});
$('chat').addEventListener('click',e=>{try{const copy=e.target.closest('.copyBtn');if(copy){const ans=copy.closest('.answer');navigator.clipboard?.writeText(ans?.innerText||'').catch?.(()=>{});copy.textContent='✓';setTimeout(()=>copy.textContent='⧉',900)}const regen=e.target.closest('.regenBtn');if(regen&&!busy){const last=chatHistory[chatHistory.length-1];if(last){$('input').value=last.q||'';autoGrow();send()}}const tts=e.target.closest('.ttsBtn');if(tts){const ans=tts.closest('.answer');if('speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(ans?.innerText||'');u.lang=/[\u0600-\u06FF]/.test(ans?.innerText||'')?'tr-TR':(/[ıİşŞğĞüÜöÖçÇ]/.test(ans?.innerText||'')?'tr-TR':'en-US');speechSynthesis.speak(u)}}}catch(e){}});
try{window.addEventListener('resize',()=>{if(document.activeElement===$('input'))document.body.classList.add('keyboard-active');else document.body.classList.remove('keyboard-active')})}catch(e){}
})();

</script>
<script>

