        { cat: "Antik Çağ", period: "MÖ 221 – MS 220; MÖ 27 – MS 476", title: "Han Çin’i, Roma ve İpek Yolu Dünyası", summary: "Büyük imparatorlukların yolları, hukuk ve idare sistemleri; Avrasya boyunca mal, fikir ve hastalık dolaşımını hızlandırdı.", places: "Roma ve Akdeniz; Chang’an; Orta Asya vahaları; Part ve Kuşan bölgeleri", concepts: ["İpek Yolu", "yurttaşlık", "hukuk", "kâğıt", "şehir altyapısı"] },
        { cat: "Antik Çağ", period: "MÖ ~300 – MS ~700", title: "Afrika ve Amerika’da Kent Uygarlıkları", summary: "Akdeniz dışındaki toplumlarda da büyük kentler, anıtsal mimari, yazı ve hassas takvimler gelişti.", places: "Maya kentleri; Teotihuacan; Moche kıyıları; Aksum; Nok kültürü; Büyük Zimbabve’nin erken öncülleri", concepts: ["Maya yazısı", "sulama", "takvim", "ticaret", "anıtsal mimari"] },
        { cat: "Orta Çağ", period: "MS 500 – 1000", title: "Yeni İmparatorluklar ve İnanç Ağları", summary: "Roma sonrası Avrupa’nın dönüşümü, Bizans’ın devamlılığı ve İslam’ın doğuşu yeni bilgi ve ticaret ağları kurdu.", places: "Konstantinopolis; Şam ve Bağdat; Mekke ve Medine; Tang Çin’i; Sahel ve Sahra kervan yolları", concepts: ["Bizans", "İslam’ın doğuşu", "manastırlar", "kervan ticareti", "kâğıt üretimi"] },
        { cat: "Orta Çağ", period: "MS 800 – 1300", title: "Bilgi Merkezleri ve Kıtalararası Değişim", summary: "Çeviri hareketleri, üniversiteler ve büyük ticaret yolları matematik, tıp, astronomi ve teknolojinin dolaşımını sağladı.", places: "Bağdat; Kahire; Kurtuba; Timbuktu; Konstantinopolis; Kaifeng; Nalanda", concepts: ["cebir", "hastane", "üniversite", "pusula", "barut"] },
        { cat: "Orta Çağ", period: "MS 900 – 1500", title: "Afrika, Amerika ve Okyanusya’nın Güçlü Toplumları", summary: "Küresel tarih, Avrasya’nın ötesinde de şehirleri, devletleri ve denizcilik ağlarını kapsar; bu toplumların kendi dinamikleri vardı.", places: "Mali ve Songhay; Büyük Zimbabve; Cusco ve Andlar; Tenochtitlan; Angkor; Polinezya", concepts: ["Mansa Musa", "teras tarımı", "chinampa", "Hint Okyanusu ticareti", "okyanus seyrüseferi"] },
        { cat: "Orta Çağ", period: "1206 – 1368", title: "Moğol İmparatorluğu ve Avrasya Bağlantıları", summary: "Moğol fetihleri geniş bir kara imparatorluğu kurdu; güvenlik, ticaret ve salgınların yayılımı üzerinde derin etkiler bıraktı.", places: "Moğolistan; Karakurum; Pekin; Orta Asya; Karadeniz bozkırları", concepts: ["Pax Mongolica", "posta ağı", "kara ticareti", "diplomasi", "Kara Ölüm"] },
        { cat: "Erken Modern", period: "~1400 – 1600", title: "Rönesans, Matbaa ve Okyanus Seferleri", summary: "Basılı bilginin çoğalması ve okyanus aşırı seferler yeni bilgi alışverişi yarattı; aynı süreç sömürgecilik, zorla çalıştırma ve büyük nüfus kayıplarını da beraberinde getirdi.", places: "Floransa ve Venedik; Mainz; Lizbon ve Sevilla; Karayipler; Aztek ve İnka toprakları", concepts: ["matbaa", "Rönesans", "Kolomb Mübadelesi", "sömürgecilik", "haritacılık"] },
        { cat: "Erken Modern", period: "~1500 – 1800", title: "Bilimsel Devrim, Reform ve Küresel Ticaret", summary: "Gözlem ve deney bilimde yeni yöntemleri güçlendirdi; imparatorluklar ve deniz ticareti küresel ekonomiyi genişletirken köle ticareti milyonlarca insanı zorla yerinden etti.", places: "Avrupa; Osmanlı ve Safevi merkezleri; Mughal Hindistan; Ming/Qing Çin’i; Atlantik kıyıları", concepts: ["bilimsel yöntem", "Reformasyon", "merkantilizm", "Atlantik köle ticareti", "küresel ağ"] },
