        { cat: "Modern Çağ", period: "~1760 – 1914", title: "Sanayi Devrimi ve İmparatorluk Çağı", summary: "Buhar gücü, fabrikalar, demiryolları ve telgraf üretim ile gündelik hayatı değiştirdi; sanayileşme eşitsizlik ve sömürgeci yayılmayla iç içe ilerledi.", places: "Britanya; Ruhr; ABD’nin kuzeydoğusu; Bombay/Mumbai; Japonya; Afrika ve Asya kolonileri", concepts: ["sanayileşme", "işçi hareketi", "buhar makinesi", "demiryolu", "elektrifikasyon"] },
        { cat: "Modern Çağ", period: "1914 – 1945", title: "Dünya Savaşları ve Kırılma Yılları", summary: "İki dünya savaşı, Holokost, soykırımlar ve kitlesel yıkım uluslararası düzeni sarstı; savaş karşıtı hukuk ve kurum arayışını hızlandırdı.", places: "Avrupa; Doğu Asya ve Pasifik; Kuzey Afrika; Hiroşima ve Nagazaki", concepts: ["total savaş", "Holokost", "dekolonizasyon hareketleri", "Birleşmiş Milletler", "insan hakları"] },
        { cat: "Çağdaş Dönem", period: "1945 – 1991", title: "Soğuk Savaş, Dekolonizasyon ve Uzay Çağı", summary: "İki kutuplu rekabet, nükleer caydırıcılık ve bağımsızlık hareketleri dünya siyasetini şekillendirdi; uzay uçuşları yeni bir bilim ve teknoloji alanı açtı.", places: "Washington ve Moskova; Bandung; Cenevre; Berlin; Baikonur; Ay", concepts: ["Soğuk Savaş", "dekolonizasyon", "nükleer çağ", "uzay yarışı", "Avrupa Birliği"] },
        { cat: "Çağdaş Dönem", period: "1991 – 2007", title: "İnternetin Yaygınlaşması ve Yeni Küresel Düzen", summary: "Soğuk Savaş sonrası devletler, kurumlar ve ticaret ağları yeniden biçimlendi; web ve cep telefonu iletişimi küresel ölçekte erişilebilir kıldı.", places: "CERN; Silikon Vadisi; küresel liman ve veri ağları", concepts: ["World Wide Web", "küreselleşme", "mobil iletişim", "Avrupa Birliği genişlemesi", "dijital bölünme"] },
        { cat: "Çağdaş Dönem", period: "2008 – 2019", title: "Akıllı Telefonlar, Sosyal Ağlar ve İklim Eylemi", summary: "Mobil platformlar gündelik iletişimi ve ekonomiyi dönüştürdü; finansal kriz, kitlesel hareketler ve iklim bilimi kamusal tartışmanın merkezine taşındı.", places: "Küresel finans merkezleri; sosyal ağ toplulukları; Paris; BM iklim konferansları", concepts: ["akıllı telefon", "sosyal medya", "2008 finans krizi", "Paris Anlaşması", "platform ekonomisi"] },
